import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { createReadStream, promises as fs } from 'fs';
import * as path from 'path';
import type { Readable } from 'stream';

/**
 * Local-disk storage outside any web root. Keys are always generated by the server (never from user input)
 * and validated again here, so a key can never escape the upload directory. Swap this class for an
 * S3-compatible driver in production if needed; callers only use put/stream/remove.
 */
@Injectable()
export class FileStorageService {
  private readonly logger = new Logger(FileStorageService.name);
  readonly root: string;

  constructor(cfg: ConfigService) {
    this.root = path.resolve(cfg.get<string>('UPLOAD_DIR') ?? './uploads');
  }

  static keyFor(id: string, variant: 'full' | 'thumb') {
    return `images/${id.slice(0, 2)}/${id}${variant === 'thumb' ? '.thumb' : ''}.jpg`;
  }

  private resolve(key: string) {
    if (!/^images\/[0-9a-f]{2}\/[0-9a-f-]{36}(\.thumb)?\.jpg$/.test(key)) throw new Error('Invalid storage key');
    const full = path.resolve(this.root, key);
    if (!full.startsWith(this.root + path.sep)) throw new Error('Invalid storage key');
    return full;
  }

  async put(key: string, data: Buffer) {
    const file = this.resolve(key);
    await fs.mkdir(path.dirname(file), { recursive: true, mode: 0o750 });
    await fs.writeFile(file, data, { mode: 0o640, flag: 'wx' });
  }

  stream(key: string): Readable { return createReadStream(this.resolve(key)); }

  async exists(key: string) { return fs.stat(this.resolve(key)).then(() => true, () => false); }

  async read(key: string) { return fs.readFile(this.resolve(key)); }

  async remove(...keys: string[]) {
    for (const key of keys) {
      await fs.unlink(this.resolve(key)).catch((e: NodeJS.ErrnoException) => { if (e.code !== 'ENOENT') this.logger.warn(`Could not delete ${key}: ${e.message}`); });
    }
  }
}
